    # Malformed cursors (wrong shape, non-numeric score, etc.) -> ValueError.
    if not isinstance(cursor, str):
        raise ValueError("malformed cursor")
    parts = cursor.split("|")
    if len(parts) != 2:
        raise ValueError("malformed cursor")
    score_text, id_ = parts
    if not score_text:
        raise ValueError("malformed cursor")
    try:
        score = float(score_text)
    except ValueError:
        raise ValueError("malformed cursor")
    if not math.isfinite(score):
        raise ValueError("malformed cursor")
    return score, id_


